/bin/bash -lc 'PATH=/opt/conda/bin:$PATH pvpython - <<'"'PY'
from paraview.simple import *
r=XMLImageDataReader(FileName=['/workspace/QMCPACK.vti'])
s=TTKTopologicalSimplificationByPersistence(Input=r)
s.InputArray=['POINTS','Scalars_']; s.PersistenceThreshold=0.04; s.ThresholdIsAbsolute=1
try:
 s.UpdatePipeline(); print('simplified',s.GetDataInformation().GetNumberOfPoints(), [s.GetDataInformation().GetPointDataInformation().GetArrayInformation(i).GetName() for i in range(s.GetDataInformation().GetPointDataInformation().GetNumberOfArrays())])
except Exception as e: print('SIMP ERR',e)
c=TTKScalarFieldCriticalPoints(Input=s); c.ScalarField=['POINTS','Scalars_']
try:
 c.UpdatePipeline(); print('crit ports',c.GetDataInformation().GetNumberOfPoints()); print('arrays', [c.GetDataInformation().GetPointDataInformation().GetArrayInformation(i).GetName() for i in range(c.GetDataInformation().GetPointDataInformation().GetNumberOfArrays())])
except Exception as e: print('CRIT ERR',e)
PY"

